// BuiltinTable holds direct *eval.Builtin pointers indexed by
// the same numeric operand the compiler emits. Populated and
// validated by init() — see below.
var BuiltinTable [NumBuiltins]*eval.Builtin

// init wires BuiltinTable from eval.Builtins and verifies the
// generated table is in sync with the runtime registry. Any drift
// (missing builtin, extra builtin, or rename) panics at startup
// with the offending name — never silent corruption.
//
// Regenerate with: go generate ./vm/...
func init() {
	for name, idx := range BuiltinIndex {
		b, ok := eval.Builtins[name]
		if !ok {
			panic("vm: generated builtin table references missing eval.Builtins[\"" + name + "\"] — regenerate with `go generate ./vm/...`")
		}
		BuiltinTable[idx] = b
	}
	// Reverse check: did eval/ gain builtins we don't know about?
	if got, want := len(eval.Builtins), NumBuiltins; got != want {
		panic("vm: eval.Builtins has " + itoa(got) + " entries but generated table has " + itoa(want) + " — regenerate with `go generate ./vm/...`")
	}
}
